import Foundation
import SwiftUI

enum AppLanguage: String, CaseIterable, Identifiable {
    case italian = "it"
    case english = "en"
    case spanish = "es"
    case french = "fr"
    case chinese = "zh-Hans"
    case arabic = "ar"
    case danish = "da"
    case norwegian = "nb"
    case swedish = "sv"

    var id: String { rawValue }

    var locale: Locale {
        Locale(identifier: rawValue)
    }

    var displayName: String {
        switch self {
        case .italian: return "Italiano"
        case .english: return "English"
        case .spanish: return "Español"
        case .french: return "Français"
        case .chinese: return "中文"
        case .arabic: return "العربية"
        case .danish: return "Dansk"
        case .norwegian: return "Norsk"
        case .swedish: return "Svenska"
        }
    }

    var aiLanguageName: String {
        switch self {
        case .italian: return "Italian"
        case .english: return "English"
        case .spanish: return "Spanish"
        case .french: return "French"
        case .chinese: return "Simplified Chinese"
        case .arabic: return "Arabic"
        case .danish: return "Danish"
        case .norwegian: return "Norwegian"
        case .swedish: return "Swedish"
        }
    }

    var weekdaySymbolsMondayFirst: [String] {
        switch self {
        case .italian: return ["Lu", "Ma", "Me", "Gi", "Ve", "Sa", "Do"]
        case .english: return ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"]
        case .spanish: return ["Lu", "Ma", "Mi", "Ju", "Vi", "Sa", "Do"]
        case .french: return ["Lu", "Ma", "Me", "Je", "Ve", "Sa", "Di"]
        case .chinese: return ["周一", "周二", "周三", "周四", "周五", "周六", "周日"]
        case .arabic: return ["اث", "ثل", "أر", "خم", "جم", "سب", "أح"]
        case .danish: return ["ma", "ti", "on", "to", "fr", "lø", "sø"]
        case .norwegian: return ["ma", "ti", "on", "to", "fr", "lø", "sø"]
        case .swedish: return ["må", "ti", "on", "to", "fr", "lö", "sö"]
        }
    }

    static func bestMatch(for localeIdentifier: String) -> AppLanguage {
        let lowered = localeIdentifier.lowercased()

        if lowered.hasPrefix("it") { return .italian }
        if lowered.hasPrefix("en") { return .english }
        if lowered.hasPrefix("es") { return .spanish }
        if lowered.hasPrefix("fr") { return .french }
        if lowered.hasPrefix("zh") { return .chinese }
        if lowered.hasPrefix("ar") { return .arabic }
        if lowered.hasPrefix("da") { return .danish }
        if lowered.hasPrefix("nb") || lowered.hasPrefix("nn") || lowered.hasPrefix("no") { return .norwegian }
        if lowered.hasPrefix("sv") { return .swedish }

        return .italian
    }
}

enum AppLanguagePreferences {
    static let storageKey = "mindmesh.app.language"

    static var currentLanguage: AppLanguage {
        get {
            if let rawValue = UserDefaults.standard.string(forKey: storageKey),
               let language = AppLanguage(rawValue: rawValue) {
                return language
            }

            let preferredLocale = Locale.preferredLanguages.first ?? Locale.current.identifier
            return AppLanguage.bestMatch(for: preferredLocale)
        }
        set {
            UserDefaults.standard.set(newValue.rawValue, forKey: storageKey)
        }
    }
}

@MainActor
final class AppLanguageStore: ObservableObject {
    @Published var selectedLanguage: AppLanguage {
        didSet {
            AppLanguagePreferences.currentLanguage = selectedLanguage
        }
    }

    init(initialLanguage: AppLanguage = AppLanguagePreferences.currentLanguage) {
        self.selectedLanguage = initialLanguage
    }
}

