    func supportWelcome(snapshotTitle: String?) -> String {
        if let snapshotTitle {
            return text(
                it: "Questa chat premium ti aiuta a mettere ordine nelle emozioni difficili, senza fare diagnosi. Dal tuo andamento recente emerge questo: \(snapshotTitle.lowercased())\n\nSe vuoi, raccontami cosa pesa di piu oggi e proviamo a scomporlo insieme.",
                en: "This premium chat helps you sort through difficult emotions without making diagnoses. Your recent pattern suggests this: \(snapshotTitle.lowercased())\n\nIf you want, tell me what feels heaviest today and we can break it down together.",
                es: "Este chat premium te ayuda a ordenar emociones difíciles sin hacer diagnósticos. De tu tendencia reciente emerge esto: \(snapshotTitle.lowercased())\n\nSi quieres, cuéntame qué pesa más hoy y lo descomponemos juntos.",
                fr: "Ce chat premium t'aide à mettre de l'ordre dans les émotions difficiles, sans poser de diagnostic. Voici ce qui ressort de ta tendance récente : \(snapshotTitle.lowercased())\n\nSi tu veux, raconte-moi ce qui pèse le plus aujourd'hui et on peut le décomposer ensemble.",
                zh: "这个 Premium 聊天会帮助你梳理复杂情绪，而不会做出诊断。你最近的状态里最明显的是：\(snapshotTitle.lowercased())\n\n如果你愿意，可以告诉我今天最让你有压力的是什么，我们一起把它拆开来看。",
                ar: "تساعدك هذه الدردشة المميزة على ترتيب المشاعر الصعبة من دون تشخيص. هذا ما يظهر من اتجاهك الأخير: \(snapshotTitle.lowercased())\n\nإذا أردت، أخبرني ما الذي يثقل عليك أكثر اليوم وسنحاول تفكيكه معاً.",
                da: "Denne premium-chat hjælper dig med at skabe orden i svære følelser uden at stille diagnoser. Dit seneste mønster peger på dette: \(snapshotTitle.lowercased())\n\nHvis du vil, så fortæl mig, hvad der fylder mest i dag, så kan vi dele det op sammen.",
                nb: "Denne premium-chatten hjelper deg med å sortere vanskelige følelser uten å stille diagnoser. Dette ser ut til å komme fram i mønsteret ditt i det siste: \(snapshotTitle.lowercased())\n\nHvis du vil, kan du fortelle hva som tynger mest i dag, så kan vi dele det opp sammen.",
                sv: "Den här premiumchatten hjälper dig att sortera svåra känslor utan att ställa diagnoser. Det här framträder i ditt senaste mönster: \(snapshotTitle.lowercased())\n\nOm du vill kan du berätta vad som känns tyngst idag, så kan vi bryta ner det tillsammans."
            )
        }

        return text(
            it: "Questa chat premium ti aiuta a dare un nome alle emozioni difficili e a renderle piu leggibili, senza fare diagnosi o sostituire un professionista.\n\nScrivimi cosa senti in questo momento, anche in modo disordinato.",
            en: "This premium chat helps you name difficult emotions and make them easier to understand, without diagnosing or replacing a professional.\n\nWrite to me about what you're feeling right now, even if it comes out messy.",
            es: "Este chat premium te ayuda a poner nombre a las emociones difíciles y a hacerlas más comprensibles, sin diagnosticar ni sustituir a un profesional.\n\nEscríbeme lo que sientes ahora mismo, aunque salga desordenado.",
            fr: "Ce chat premium t'aide à nommer les émotions difficiles et à les rendre plus lisibles, sans poser de diagnostic ni remplacer un professionnel.\n\nÉcris-moi ce que tu ressens maintenant, même de façon désordonnée.",
            zh: "这个 Premium 聊天会帮助你给复杂情绪命名，并让它们更容易理解，不会做诊断，也不能替代专业人士。\n\n把你现在的感受写给我，哪怕很混乱也没关系。",
            ar: "تساعدك هذه الدردشة المميزة على تسمية المشاعر الصعبة وجعلها أوضح، من دون تشخيص أو استبدال مختص.\n\nاكتب لي ما تشعر به الآن، حتى لو كان بشكل غير مرتب.",
            da: "Denne premium-chat hjælper dig med at sætte ord på svære følelser og gøre dem lettere at forstå uden at stille diagnoser eller erstatte en professionel.\n\nSkriv til mig, hvad du føler lige nu, også selv om det er rodet.",
            nb: "Denne premium-chatten hjelper deg med å sette ord på vanskelige følelser og gjøre dem lettere å forstå, uten å stille diagnoser eller erstatte en profesjonell.\n\nSkriv til meg hva du føler akkurat nå, selv om det kommer usortert.",
            sv: "Den här premiumchatten hjälper dig att sätta ord på svåra känslor och göra dem mer begripliga, utan att ställa diagnoser eller ersätta en professionell.\n\nSkriv till mig hur du känner just nu, även om det blir rörigt."
        )
    }
