    var purchaseLoadingProducts: String { text(it: "Sto caricando le opzioni di acquisto da App Store.", en: "Loading purchase options from the App Store.", es: "Cargando opciones de compra desde App Store.", fr: "Chargement des options d'achat depuis l'App Store.", zh: "正在从 App Store 加载购买选项。", ar: "جارٍ تحميل خيارات الشراء من App Store.", da: "Indlæser købsmuligheder fra App Store.", nb: "Laster inn kjøpsalternativer fra App Store.", sv: "Laddar köpalternativ från App Store.") }
