    var purchaseUnknownState: String { text(it: "Stato acquisto non riconosciuto.", en: "Unrecognized purchase state.", es: "Estado de compra no reconocido.", fr: "État d'achat non reconnu.", zh: "无法识别的购买状态。", ar: "حالة شراء غير معروفة.", da: "Ukendt købstatus.", nb: "Ukjent kjøpstilstand.", sv: "Okänt köpstatus.") }
